const scope=$('Fetch Active Scope Metadata').first().json;
const doc=$('Read Active Google Doc').first()?.json || {};
const issueItems=($('Read GitHub Issues').all() || []).flatMap(i=>Array.isArray(i.json)?i.json:[i.json]);
function collectText(value,out=[]){if(!value)return out;if(Array.isArray(value)){for(const v of value)collectText(v,out);return out;}if(typeof value==='object'){if(typeof value.content==='string')out.push(value.content);for(const v of Object.values(value))collectText(v,out);}return out;}
const docMissing=!doc.documentId||!!doc.error;
const docText=docMissing?'':collectText(doc.body?.content||[]).join('').slice(0,12000);
const issues=issueItems.filter(i=>i && !i.pull_request).map(i=>({number:i.number,title:i.title,state:i.state,labels:(i.labels||[]).map(l=>typeof l==='string'?l:l.name),updated_at:i.updated_at,url:i.html_url}));
const evidence=[
  {
    provider:'google_docs',
    resource_id:scope.document_id,
    provider_revision:doc.revisionId||scope.provider_revision||'',
    excerpt:docMissing?'MISSING_OR_UNREADABLE_ACTIVE_SCOPE_DOCUMENT':docText.slice(0,4000),
    safe_url:docMissing?'':`https://docs.google.com/document/d/${scope.document_id}/edit`
  },
  {
    provider:'github',
    resource_id:`${scope.repo_owner}/${scope.repo_name}:issues`,
    provider_revision:new Date().toISOString(),
    excerpt:JSON.stringify(issues).slice(0,4000),
    safe_url:`https://github.com/${scope.repo_owner}/${scope.repo_name}/issues`
  }
];
const agent_input=`CASE INVESTIGATION TASK:
Case ID: ${scope.case_id}
Project ID: ${scope.project_id}
Project Name: ${scope.project_name}

CLIENT INTAKE REQUEST:
"""
${scope.request_excerpt}
"""

ACTIVE SCOPE METADATA (Version ${scope.scope_version}):
${JSON.stringify(scope.normalized_scope, null, 2)}

INITIAL EVIDENCE SUMMARY:
- Google Doc Status: ${docMissing ? 'MISSING OR UNREADABLE' : 'RETRIEVED'} (Length: ${docText.length} chars)
- Open GitHub Issues: ${issues.length} issues loaded

INSTRUCTIONS:
Investigate whether this request is:
1) "covered": already included in current deliverables or open GitHub tasks.
2) "additional": represents a new deliverable, scope swap, or chargeable addition.
3) "ambiguous": missing evidence, unreadable scope doc, contradictory terms, or requires manager clarification.

Use your MCP tools (Project_Context, Case_Evidence) if you need additional project metadata or case evidence snapshots. When complete, provide your structured recommendation matching the required JSON schema.`;

return [{json:{case_id:scope.case_id,project_id:scope.project_id,project_name:scope.project_name,doc_missing:docMissing,evidence,issues,normalized_scope:scope.normalized_scope,agent_input}}];

const context = $('Assemble Investigation Prompt & Evidence').first().json;
const rawInput = $json.output || $json.text || $json.message?.content || $json;

let rec = null;
let isFallback = false;

// Detect agent failure, timeout, or empty response
if ($json.error || !rawInput) {
  isFallback = true;
} else if (typeof rawInput === 'object' && rawInput.classification) {
  rec = rawInput;
} else if (typeof rawInput === 'string') {
  try {
    const cleaned = rawInput.replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
    rec = JSON.parse(cleaned);
  } catch (e) {
    isFallback = true;
  }
}

const ALLOWED_CLASSIFICATIONS = new Set(['covered', 'additional', 'ambiguous']);

if (!rec || isFallback) {
  rec = {
    classification: 'ambiguous',
    summary: 'Automated AI investigation was inconclusive, timed out, or unavailable. Escalated for human manager review.',
    evidence: [],
    gaps: ['AI model investigation could not be validated or exceeded budget limit. Escalated for manager manual review.'],
    suggested_options: [
      {
        kind: 'clarify',
        description: 'Review client change request manually and clarify scope requirements with client.',
        added_deliverables: [],
        removed_deliverable_ids: [],
        manager_confirmation_required: true
      }
    ],
    confidence: 0.2
  };
} else {
  // Normalize legacy 'change' to 'additional'
  if (rec.classification === 'change') rec.classification = 'additional';
  if (!ALLOWED_CLASSIFICATIONS.has(rec.classification)) {
    rec.classification = 'ambiguous';
    rec.gaps = (rec.gaps || []).concat(['Model returned invalid classification; safely escalated to ambiguous.']);
  }

  // Enforce Missing Scope Document rule (Requirement 10)
  if (context.doc_missing) {
    rec.classification = 'ambiguous';
    rec.confidence = Math.min(Number(rec.confidence || 0.4), 0.5);
    rec.gaps = (rec.gaps || []).concat(['The active scope document was missing or unreadable. Manager review required.']);
  }

  // Validate deliverable IDs against active baseline
  const knownDeliverableIds = new Set((context.normalized_scope?.deliverables || []).map(d => d.id));
  if (Array.isArray(rec.suggested_options)) {
    for (const opt of rec.suggested_options) {
      opt.manager_confirmation_required = true; // Strict read-only enforcement
      if (Array.isArray(opt.removed_deliverable_ids)) {
        opt.removed_deliverable_ids = opt.removed_deliverable_ids.filter(id => knownDeliverableIds.has(id));
      } else {
        opt.removed_deliverable_ids = [];
      }
      if (!Array.isArray(opt.added_deliverables)) {
        opt.added_deliverables = [];
      }
    }
  } else {
    rec.suggested_options = [];
  }

  // Validate GitHub issue references
  const knownIssueNumbers = new Set((context.issues || []).map(i => i.number));
  if (Array.isArray(rec.evidence)) {
    for (const ev of rec.evidence) {
      if (typeof ev.excerpt === 'string' && ev.excerpt.length > 600) {
        ev.excerpt = ev.excerpt.slice(0, 600);
      }
    }
  } else {
    rec.evidence = [];
  }
}

// Database contract for scopeledger.record_investigation_result
const dbRecommendation = {
  classification: rec.classification,
  summary: rec.summary || rec.reasoning || '',
  reasoning: rec.summary || rec.reasoning || '',
  confidence: rec.confidence ?? (rec.classification === 'ambiguous' ? 0.4 : 0.85),
  evidence_refs: rec.evidence || [],
  gaps: rec.gaps || [],
  recommended_options: (rec.suggested_options || []).map(opt => ({
    kind: opt.kind,
    description: opt.description,
    added_deliverables: opt.added_deliverables || [],
    removed_deliverable_ids: opt.removed_deliverable_ids || [],
    manager_confirmation_required: true
  }))
};

return [{
  json: {
    case_id: context.case_id,
    recommendation: dbRecommendation,
    evidence: context.evidence
  }
}];
